import csv
import json
from flask import Flask, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

CSV_PATH = "uploads/sensor_readings.csv"


def read_csv():
    readings = []
    with open(CSV_PATH, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            readings.append({
                "timestamp": row["timestamp"],
                "sensor": row["sensor"],
                "temperature_c": float(row["temperature_c"]),
            })
    return readings


@app.route("/api/readings")
def api_readings():
    return jsonify(read_csv())


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=3000)

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 8000,
    host: '0.0.0.0',
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true,
      },
    },
  },
})

import { useState, useEffect } from "react";
import "./App.css";

function SummaryCard({ readings }) {
  if (!readings.length) return null;

  const temps = readings.map((r) => r.temperature_c);
  const count = readings.length;
  const min = Math.min(...temps);
  const max = Math.max(...temps);

  return (
    <div className="summary-card">
      <h2>Summary</h2>
      <div className="summary-grid">
        <div className="summary-item">
          <span className="label">Total Readings</span>
          <span className="value">{count}</span>
        </div>
        <div className="summary-item">
          <span className="label">Min Temperature</span>
          <span className="value">{min.toFixed(1)} °C</span>
        </div>
        <div className="summary-item">
          <span className="label">Max Temperature</span>
          <span className="value">{max.toFixed(1)} °C</span>
        </div>
      </div>
    </div>
  );
}

function DataTable({ readings }) {
  if (!readings.length) return null;

  return (
    <div className="table-wrapper">
      <h2>Readings</h2>
      <table>
        <thead>
          <tr>
            <th>Timestamp</th>
            <th>Sensor</th>
            <th>Temperature (°C)</th>
          </tr>
        </thead>
        <tbody>
          {readings.map((r, i) => (
            <tr key={i}>
              <td>{r.timestamp}</td>
              <td>{r.sensor}</td>
              <td>{r.temperature_c.toFixed(1)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function App() {
  const [readings, setReadings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch("/api/readings")
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(setReadings)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="app">
      <h1>🌡️ Sensor Dashboard</h1>

      {loading && <p className="loading">Loading sensor data…</p>}
      {error && <p className="error">Error: {error}</p>}

      {!loading && !error && (
        <>
          <SummaryCard readings={readings} />
          <DataTable readings={readings} />
        </>
      )}
    </div>
  );
}

#root {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 1.5rem;
  color: #1a1a2e;
}

/* Summary cards */
.summary {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
}

.card {
  flex: 1;
  background: #f0f4ff;
  border-radius: 12px;
  padding: 1.25rem;
  text-align: center;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}

.card .label {
  font-size: 0.85rem;
  color: #666;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.4rem;
}

.card .value {
  font-size: 1.6rem;
  font-weight: 700;
  color: #1a1a2e;
}

/* Table */
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

thead th {
  text-align: left;
  padding: 0.75rem 1rem;
  background: #1a1a2e;
  color: #fff;
  font-weight: 600;
}

thead th:first-child {
  border-radius: 8px 0 0 0;
}

thead th:last-child {
  border-radius: 0 8px 0 0;
}

tbody td {
  padding: 0.6rem 1rem;
  border-bottom: 1px solid #e8e8e8;
}

tbody tr:hover {
  background: #f7f9ff;
}

tbody tr:last-child td:first-child {
  border-radius: 0 0 0 8px;
}

tbody tr:last-child td:last-child {
  border-radius: 0 0 8px 0;
}

/* Loading / error states */
.loading,
.error {
  text-align: center;
  padding: 3rem;
  font-size: 1.1rem;
  color: #888;
}

.error {
  color: #c0392b;
}
